const fs = require('node:fs');
const path = require('node:path');
const { randomUUID } = require('node:crypto');
const { projectImageDimensions } = require('../features/workspace/project-images.cjs');
const { isImageFile } = require('../features/files/file-cards.cjs');

function createImageTools({ nativeImage, BrowserWindow, previewResources }) {
  // Pictures in the reading view (generated by Codex, or pasted with a message) travel as a JPEG at most 640 pixels
  // wide; a small picture stays as it was.
  const thumbnail = image => {
    if (image.isEmpty() || image.getSize().width <= 640) return null;
    return `data:image/jpeg;base64,${image.resize({ width: 640, quality: 'good' }).toJPEG(86).toString('base64')}`;
  };
  const small = image => thumbnail(image) || (image.isEmpty() ? null : image.toDataURL());
  const pictureOf = file => small(nativeImage.createFromPath(file));
  function thumbnailProjectImage(bytes, source) {
    if (!projectImageDimensions(bytes, source)) return null;
    const image = nativeImage.createFromBuffer(bytes);
    if (image.isEmpty()) return null;
    const { width, height } = image.getSize(), side = Math.min(width, height);
    if (side < (source === 'icon' ? 16 : 48) || Math.max(width, height) > side * 4 || width * height > 40_000_000) return null;
    const square = image.crop({ x: Math.floor((width - side) / 2), y: Math.floor((height - side) / 2), width: side, height: side }).resize({ width: 256, height: 256, quality: 'good' });
    const png = square.toDataURL();
    return png.length <= 200_000 ? png : `data:image/jpeg;base64,${square.toJPEG(82).toString('base64')}`;
  }

  // A picture's bytes, from where a page loaded it, as an image for the clipboard. PNG and JPEG decode here; WebP, GIF,
  // SVG and AVIF are decoded by Chromium in the app's own page, which hands back a PNG.
  const PICTURE_LIMIT = 50 * 1024 * 1024;
  async function pictureFrom(contents, src) {
    if (!src) return null;
    if (src.startsWith('data:')) { const image = nativeImage.createFromDataURL(src); if (!image.isEmpty()) return image; }
    let bytes, type;
    if (previewResources.hasUrl(src)) {
      const resource = await previewResources.resolve(src);
      if (resource.size > PICTURE_LIMIT) return null;
      bytes = resource.readChunk ? await resource.readChunk(0, resource.size) : await fs.promises.readFile(resource.path);
      type = resource.mimeType;
    } else if (src.startsWith('data:')) {
      const match = /^data:([^;,]+)?(;base64)?,(.*)$/s.exec(src);
      if (!match) return null;
      bytes = match[2] ? Buffer.from(match[3], 'base64') : Buffer.from(decodeURIComponent(match[3])); type = match[1] || 'image/png';
    } else {
      const response = await contents.session.fetch(src);
      if (!response.ok) return null;
      bytes = Buffer.from(await response.arrayBuffer()); type = response.headers.get('content-type') || '';
      if (bytes.length > PICTURE_LIMIT) return null;
    }
    const image = nativeImage.createFromBuffer(bytes);
    if (!image.isEmpty()) return image;
    const owner = BrowserWindow.fromWebContents(contents) ?? BrowserWindow.getAllWindows()[0];
    const png = await owner?.webContents.executeJavaScript(`(async source => {
      const picture = new Image(); picture.src = source; await picture.decode();
      const canvas = document.createElement('canvas'); canvas.width = picture.naturalWidth || 1024; canvas.height = picture.naturalHeight || 1024;
      canvas.getContext('2d').drawImage(picture, 0, 0, canvas.width, canvas.height);
      return canvas.toDataURL('image/png');
    })(${JSON.stringify(`data:${(type || 'image/png').split(';')[0]};base64,${bytes.toString('base64')}`)})`, true);
    return typeof png === 'string' ? nativeImage.createFromDataURL(png) : null;
  }
  return { thumbnail, small, pictureOf, thumbnailProjectImage, pictureFrom };
}

function registerImageIpc({ handle, app, findProject, getSession, clipboard, nativeImage, isGeneratedImage }) {
  // A picture pasted where the agent cannot take it from the clipboard: before it runs (the decisions' "what next"), or
  // on another computer over SSH, whose CLI has no way to this one's clipboard. It is kept as a file where the agent
  // runs (this profile, or that computer's temporary folder) and its path goes with the message for the agent to open.
  // A week later the next one clears it away.
  async function saveAgentImage(terminalId, data, extension) {
    const project = findProject(terminalId), s = getSession(terminalId);
    if (!data.length || data.length > 25 * 1024 * 1024) throw new Error('图片太大（超过 25 MB），请压缩后再粘贴。');
    if (project.kind === 'ssh') {
      if (!s?.terminal?.request) throw new Error('SSH 连接已断开，请重新连接。');
      const transfer = await s.terminal.request('image-start', { extension, size: data.length });
      try {
        for (let offset = 0; offset < data.length; offset += 256 * 1024) {
          await s.terminal.request('upload-chunk', { transfer: transfer.id, offset, data: data.subarray(offset, offset + 256 * 1024).toString('base64') });
        }
        return (await s.terminal.request('upload-finish', { transfer: transfer.id })).path;
      } catch (error) { await s.terminal.request('upload-cancel', { transfer: transfer.id }).catch(() => {}); throw error; }
    }
    const folder = path.join(app.getPath('userData'), 'attachments');
    await fs.promises.mkdir(folder, { recursive: true });
    const old = Date.now() - 7 * 24 * 3600 * 1000;
    for (const name of await fs.promises.readdir(folder).catch(() => [])) {
      const file = path.join(folder, name);
      if ((await fs.promises.stat(file).catch(() => null))?.mtimeMs < old) await fs.promises.rm(file, { force: true }).catch(() => {});
    }
    const file = path.join(folder, `${new Date().toISOString().replace(/[:.]/g, '-')}-${randomUUID().slice(0, 8)}.${extension}`);
    await fs.promises.writeFile(file, data);
    return file;
  }
  handle('agent:saveImage', async (terminalId, bytes, type) => {
    const extension = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'image/gif': 'gif' }[type];
    if (!extension || !(bytes instanceof Uint8Array || bytes instanceof ArrayBuffer)) throw new Error('只能附加 PNG、JPEG、WebP 或 GIF 图片。');
    return saveAgentImage(terminalId, Buffer.from(bytes instanceof ArrayBuffer ? new Uint8Array(bytes) : bytes), extension);
  });
  // The picture on the clipboard, for an SSH terminal's agent: saved on that computer, and its path given back to be
  // pasted in its place. Null when the clipboard holds no picture (its text is pasted as usual then). Only reads.
  handle('agent:clipboardImage', async terminalId => {
    if (findProject(terminalId).kind !== 'ssh') return null;
    const image = clipboard.readImage();
    return image.isEmpty() ? null : saveAgentImage(terminalId, image.toPNG(), 'png');
  });
  // A picture the reading view shows (one Codex generated, or an image file a card shows), large enough to look at in
  // its popup: at most 2400 pixels wide. Only an image file is read this way, never opened in another program.
  handle('agent:image', async file => {
    if (!(isGeneratedImage(file) || isImageFile(file) && path.isAbsolute(file)) || !fs.statSync(file, { throwIfNoEntry: false })?.isFile()) throw new Error('只能显示图片文件。');
    const image = nativeImage.createFromPath(file);
    if (image.isEmpty()) throw new Error('无法读取这张图片。');
    const { width, height } = image.getSize();
    return { url: width > 2400 ? `data:image/jpeg;base64,${image.resize({ width: 2400, quality: 'best' }).toJPEG(90).toString('base64')}` : image.toDataURL(), width, height };
  });
}

module.exports = { createImageTools, registerImageIpc };
